# Q1: star-4 (class + age + city + name)
# dataset: social
# A subject star with one constant object (10% of the persons are :C3).
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX : <http://example.org/social/>
SELECT ?x ?a ?c ?n
WHERE {
  ?x rdf:type :C3 ;
     :age ?a ;
     :city ?c ;
     :name ?n .
}

# Q2: BSBM product star-6
# dataset: bsbm
# A six-pattern product star anchored on one popular feature.
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX bsbm: <http://example.org/bsbm/vocabulary/>
PREFIX inst: <http://example.org/bsbm/instances/>
SELECT ?product ?type ?label ?producer ?n1 ?t1
WHERE {
  ?product bsbm:productFeature inst:ProductFeature3 ;
           rdf:type ?type ;
           rdfs:label ?label ;
           bsbm:producer ?producer ;
           bsbm:productPropertyNumeric1 ?n1 ;
           bsbm:productPropertyTextual1 ?t1 .
}

# Q5: OPTIONAL with a type check inside
# dataset: social
# Every :C3 person, with the :C4 persons they know (unbound when there are none).
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX : <http://example.org/social/>
SELECT ?x ?y
WHERE {
  ?x rdf:type :C3 .
  OPTIONAL {
    ?x :knows ?y .
    ?y rdf:type :C4 .
  }
}

# Q11: UNION
# dataset: social
# Outgoing :knows of :C1 persons plus incoming :knows of :C2 persons.
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX : <http://example.org/social/>
SELECT ?x ?y
WHERE {
  { ?x rdf:type :C1 . ?x :knows ?y . }
  UNION
  { ?x rdf:type :C2 . ?y :knows ?x . }
}

# Q12: MINUS
# dataset: social
# :C5 persons who know no other :C5 person (?x is shared, so MINUS = NOT EXISTS here).
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX : <http://example.org/social/>
SELECT ?x
WHERE {
  ?x rdf:type :C5 .
  MINUS {
    ?x :knows ?y .
    ?y rdf:type :C5 .
  }
}

# Q16: COUNT(*) {?s ?p ?o}
# dataset: social
# Size of the default graph.
SELECT (COUNT(*) AS ?count)
WHERE {
  ?s ?p ?o .
}
